NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'Song of Solomon'

CHAPTERS = {
    1: {
        1: 'Pesem pesmi, ki je Salomonova.',
        2: 'Naj me poljublja s poljubi svojih ust, kajti tvoja ljubezen je boljša kakor vino.',
        3: 'Zaradi vonja tvojih dobrih mazil je tvoje ime kakor izlito mazilo, zato te ljubijo device.',
        4: 'Povleci me, me bomo tekle za teboj. Kralj me je privedel v svoje sobe; me bomo vesele in se veselile v tebi, me se bomo spominjale tvoje ljubezni bolj kakor vina. Poštene te ljubijo.',
        5: 'Črna sem, toda ljubka, oh ve hčere jeruzalemske, kakor kedárski šotori, kakor Salomonove zavese.',
        6: 'Ne glejte name, ker sem počrnela, ker je name pogledalo sonce. Otroci moje matere so bili jezni name, postavili so me za varuhinjo vinogradov, toda svojega lastnega vinograda nisem varovala.',
        7: 'Povej mi, oh ti, ki ga ljubi moja duša, kje paseš, kje daješ svojemu tropu, da počiva opoldan; kajti zakaj bi bila jaz kakor nekdo, ki se obrača vstran ob tropih tvojih družabnikov?',
        8: 'Če ne veš, oh najlepša med ženami, pojdi svojo pot naprej ob stopinjah tropa in pasi svoje kozličke poleg pastirskih šotorov.',
        9: 'Primerjal sem te, oh moja ljubezen, s skupino konj v faraonovih bojnih vozovih.',
        10: 'Tvoja lica so ljubka z nizi draguljev, tvoj vrat z verižicami iz zlata.',
        11: 'Naredile ti bomo zlate robove s srebrnimi kroglicami.',
        12: 'Medtem ko kralj sedi pri svoji mizi, moja narda oddaja svoj vonj.',
        13: 'Moj srčno ljubljeni mi je sveženj mire, vso noč bo ležal med mojimi prsmi.',
        14: 'Moj ljubljeni mi je kakor skupina kan v engedijskih vinogradih.',
        15: 'Glej, lepa si, moja ljubezen, glej, lepa si, imaš oči golobice.',
        16: 'Glej, lep si, moj ljubljeni, da, prijeten. Tudi najina postelja je zelena.',
        17: 'Bruna najine hiše so cedre in najini trami v ostrešju iz cipresovine.',
    },
    2: {
        1: 'Jaz sem vrtnica Šaróna in dolinska lilija.',
        2: 'Kakor lilija med trnjem, tako je moja ljubezen med hčerami.',
        3: 'Kakor jablana med gozdnimi drevesi, tak je moj ljubljeni med sinovi. Z velikim veseljem sem se usedla pod njeno senco in njen sad je bil sladek mojemu okusu.',
        4: 'Privedel me je v hišo gostije in njegov prapor nad menoj je bila ljubezen.',
        5: 'Potešite me s flaškoni, tolažite me z jabolki, kajti jaz sem bolna od ljubezni.',
        6: 'Njegova leva roka je pod mojo glavo in njegova desnica me objema.',
        7: 'Naročam vam, oh ve hčere jeruzalemske, pri srnah in pri poljskih košutah, da ne razvnamete niti ne zbudite moje ljubezni, dokler njemu ugaja.',
        8: 'Glas mojega ljubljenega! Glej, prihaja, skače na gorah, poskakuje po hribih.',
        9: 'Moj ljubljeni je podoben srni ali mlademu jelenu. Glej, stoji za našim zidom, gleda pri oknih, kaže se skozi mrežo.',
        10: 'Moj ljubljeni je spregovoril in mi rekel: »Vstani, moja ljubezen, moja lepotica in odleti.',
        11: 'Kajti glej, zima je minila, dež je mimo in je izginil.',
        12: 'Cvetlice se pojavljajo na zemlji, prišel je čas petja ptic in glas grlice se sliši v naši deželi,',
        13: 'figovo drevo poganja svoje zelene fige in trte z nežnim grozdjem dajejo dober vonj. Vstani, moja ljubezen, moja lepotica in odleti.',
        14: 'Oh moja golobica, ki si v skalnih razpokah, na skrivnih krajih stopnic, naj vidim tvoje obličje, naj slišim tvoj glas, kajti tvoj glas je prijeten in tvoje obličje je ljubko.«',
        15: 'Ujemite nama lisice, majhne lisice, ki plenijo trte, kajti najine trte imajo nežno grozdje.',
        16: 'Moj ljubljeni je moj in jaz sem njegova, on pase med lilijami.',
        17: 'Dokler se ne zdani in sence [ne] odletijo, se obrni, moj ljubljeni in bodi podoben srni ali mlademu jelenu na gorah Beterja.',
    },
    3: {
        1: 'Ponoči sem na svoji postelji iskala njega, ki ga ljubi moja duša; iskala sem ga, toda nisem ga našla.',
        2: 'Sedaj se bom dvignila in šla okoli mesta, po ulicah in po širokih poteh bom iskala njega, ki ga ljubi moja duša. Iskala sem ga, toda nisem ga našla.',
        3: 'Stražarji, ki hodijo po mestu, so me našli, ki sem jim rekla: »Ali ste videli njega, ki ga ljubi moja duša?«',
        4: 'Ni bilo dolgo, ko sem odšla od njih, vendar sem našla tistega, ki ga ljubi moja duša. Prijela sem ga in ga nisem hotela izpustiti, dokler ga nisem privedla v hišo svoje matere in v sobo nje, ki me je spočela.',
        5: 'Naročam vam, oh hčere jeruzalemske, pri srnah in pri poljskih košutah, da ne razvnamete niti ne zbudite moje ljubezni, dokler njemu ugaja.',
        6: 'Kdo je ta, ki prihaja iz divjine, podobna stebrom dima, odišavljena z miro in kadilom, z vsemi trgovčevimi praški?',
        7: 'Poglej njegovo posteljo, ki je Salomonova. Šestdeset hrabrih mož je okoli nje, izmed Izraelovih hrabrih.',
        8: 'Vsi držijo meče, izkušeni so v vojni; vsak človek ima svoj meč na svojem stegnu zaradi strahu ponoči.',
        9: 'Kralj Salomon si je naredil bojni voz iz libanonskega lesa.',
        10: 'Njegove stebre je naredil iz srebra, njegovo dno iz zlata, njegovo pokrivalo iz škrlata, njegova sreda je bila tlakovana z ljubeznijo do jeruzalemskih hčera.',
        11: 'Pojdite ven, oh hčere sionske in glejte kralja Salomona s krono, s katero ga je na dan njegovih zarok kronala njegova mati in na dan veselja njegovega srca.',
    },
    4: {
        1: 'Glej lepotica si, moja ljubezen, glej, lepotica si. Znotraj svojih pramenov imaš oči golobice. Tvoji lasje so kakor trop koz, ki se pojavljajo z gore Gileád.',
        2: 'Tvoji zobje so podobni tropu ovc, ki so gladko ostrižene, ki so prišle gor iz kopanja, od katerih vsaka rodi dvojčke in med njimi ni nobene jalove.',
        3: 'Tvoje ustnice so podobne škrlatnemu sukancu in tvoj govor je ljubek. Tvoja sènca so podobna koščku granatnega jabolka znotraj tvojih pramenov.',
        4: '§ Tvoj vrat je podoben Davidovemu stolpu, zgrajenemu za orožarno, na katerem visi tisoč majhnih ščitov, vsi ščiti mogočnih ljudi.',
        5: 'Tvoji dve dojki sta podobni dvema mladima srnama, ki sta dvojčici, ki se paseta med lilijami.',
        6: 'Dokler se ne zdani in sence ne odletijo, se bom spravila do gore mire in k hribu kadila.',
        7: 'Popolnoma si lepotica, moja ljubezen, madeža ni na tebi.',
        8: 'Pridi z menoj iz Libanona, moja nevesta, z menoj iz Libanona. Poglej iz vrha Amáne, iz vrha Senírja in Hermona, iz levjih brlogov, z gora leopardov.',
        9: 'Očarala si moje srce, moja sestra, moja nevesta; z enim izmed svojih očes si očarala moje srce, z eno verižico svojega vratu.',
        10: 'Kako poštena je tvoja ljubezen, moja sestra, moja nevesta! Kako mnogo boljša je tvoja ljubezen kakor vino! In vonj tvojih mazil kakor vse dišave.',
        11: 'Tvoje ustnice, oh moja nevesta, kapljajo kakor satovje. Med in mleko sta pod tvojim jezikom in vonj tvojih oblek je podoben vonju Libanona.',
        12: 'Obdan vrt je moja sestra, moja nevesta, zaprt izvir, zapečaten studenec.',
        13: 'Tvoje rastline so sadovnjak granatnih jabolk s prijetnimi sadovi; kana z nardo;',
        14: 'narda in žafran; kolmež in cimet, z vsemi kadilnimi drevesi; mira in aloja z vsemi vodilnimi dišavami;',
        15: 'vrtni studenec, vodnjak živih vodá in vodotoki iz Libanona.',
        16: 'Zbudi se, oh severni veter in pridi jug. Pihaj na moj vrt, da bodo njegove dišave lahko iztekale. Naj moj ljubljeni pride v svoj vrt in jé svoje prijetno sadje.',
    },
    5: {
        1: 'Prišel sem v svoj vrt, moja sestra, moja nevesta. Nabral sem svojo miro s svojo dišavo, pojedel sem svoje satovje s svojim medom, popil sem svoje vino s svojim mlekom. Jejta, oh prijatelja, pijta, da, obilno pijta, oh ljubljena.',
        2: 'Spim, toda moje srce bedi. To je glas mojega ljubljenega, ki trka, rekoč: »Odpri mi, moja sestra, moja ljubezen, moja golobica, moja neomadeževana, kajti moja glava je napolnjena z roso in moji prameni z nočnimi kapljami.«',
        3: 'Slekla sem svoj plašč, kako naj ga oblečem? Umila sem svoja stopala, kako naj jih omadežujem?',
        4: 'Moj ljubljeni je svojo roko položil pri lini od vrat in moja notranjost je bila spodbujena zanj.',
        5: 'Vstala sem, da odprem svojemu ljubljenemu in moje roke so kapljale z miro in moji prsti s sladko dišečo miro na ročaje zapaha.',
        6: 'Odprla sem svojemu ljubljenemu, toda moj ljubljeni se je umaknil in izginil. Moji duši ni zadostovalo, ko je govoril. Iskala sem ga, toda nisem ga mogla najti; klicala sem ga, toda ni mi dal odgovora.',
        7: 'Stražarji, ki so šli okoli mesta, so me našli, udarili so me, ranili so me. Čuvaji obzidja so mi odvzeli moje zagrinjalo.',
        8: 'Naročam vam, oh hčere jeruzalemske, če najdete mojega ljubljenega, da mu poveste, da sem bolna od ljubezni.',
        9: 'Kaj je tvoj ljubljeni več kakor drug ljubljeni, oh najlepša med ženami? Kaj je tvoj ljubljeni več kakor drug ljubljeni, da nas ti tako bremeniš?',
        10: 'Moj ljubljeni je bel in rdečkast, vodilen med deset tisoči.',
        11: 'Njegova glava je kakor najbolj čisto zlato, njegovi prameni so košati in črni kakor krokar.',
        12: 'Njegove oči so kakor oči golobice pri rekah vodá, umite z mlekom in primerno postavljene.',
        13: 'Njegova lica so kakor postelja iz dišav, kakor dišeče cvetlice. Njegove ustnice [so] podobne lilijam, ki kapljajo sladko dišečo miro.',
        14: 'Njegove roke so kakor niz zlatih prstanov napolnjene z berilom. Njegov trebuh je kakor svetla slonovina, prevlečena s safirji.',
        15: 'Njegove noge so kakor marmorni stebri, postavljeni na podstavke iz čistega zlata. Njegovo obličje je kakor Libanon, odlično kakor cedre.',
        16: 'Njegova usta so najbolj sladka. Da, on je povsem očarljiv. To je moj ljubljeni in to je moj prijatelj. Oh hčere jeruzalemske.',
    },
    6: {
        1: 'Kam je odšel tvoj ljubljeni, oh najlepša med ženami? Kam se je tvoj ljubljeni obrnil? Da ga bomo lahko iskale s teboj.',
        2: 'Moj ljubljeni je odšel dol v svoj vrt, k posteljam iz dišav, da pase na vrtovih in da nabira lilije.',
        3: 'Jaz sem svojega ljubljenega in moj ljubljeni je moj; med lilijami pase.',
        4: 'Krasna si, oh moja ljubezen, kakor Tirca, ljubka kakor Jeruzalem, strašna kakor vojska s prapori.',
        5: 'Svoje oči odvrni od mene, kajti prevzele so me. Tvoji lasje so kakor trop koz, ki se pojavljajo iz Gileáda.',
        6: 'Tvoji zobje so kakor trop ovc, ki gredo gor s kopanja, od katerih vsaka rojeva dvojčke in med njimi ni niti ene jalove.',
        7: 'Kakor košček granatnega jabolka so tvoja sènca znotraj tvojih pramenov.',
        8: 'Šestdeset je kraljic in osemdeset priležnic in devic brez števila.',
        9: 'Moja golobica, moja neomadeževana je le ena, je samo ena od svoje matere, je izbranka nje, ki jo je rodila. Hčere so jo videle in jo blagoslovile, da, kraljice in priležnice in so jo hvalile.',
        10: 'Kdo je tista, ki gleda kakor jutro, lepa kakor luna, čista kakor sonce in strašna kakor vojska s prapori?',
        11: 'Odšla sem dol v orehov vrt, da vidim sadove doline in da vidim, če trta cveti in granatna jabolka brste.',
        12: '§ Preden sem se zavedla, me je moja duša naredila podobno Aminadábovim bojnim vozovom.',
        13: '§ Vrni se, vrni se, oh Šulámka, vrni se, vrni se, da te lahko pogledamo. Kaj boste videli na Šulámki? Kot bi bila to skupina dveh vojsk.',
    },
    7: {
        1: 'Kako krasna so tvoja stopala s čevlji, oh prinčeva hči! Sklepi tvojih stegen so podobni draguljem, delo rok spretnega delavca.',
        2: '§ Tvoj popek je podoben okrogli čašici, ki noče žgane pijače. Tvoj trebuh je podoben kupu pšenice, obsutemu z lilijami.',
        3: 'Tvoji dve dojki sta podobni dvema mladima srnama, ki sta dvojčici.',
        4: 'Tvoj vrat je kakor stolp iz slonovine, tvoje oči [so] podobne ribnikom v Hešbónu, pri Batrabímskih velikih vratih. Tvoj nos je kakor libanonski stolp, ki gleda proti Damasku.',
        5: 'Tvoja glava na tebi je podobna Karmelu in lasje tvoje glave [so] podobni škrlatu; kralj je zadržan v galerijah.',
        6: 'Kako lepa in kako prijetna si ti, oh ljubezen, za naslade!',
        7: 'Ta tvoja postava je podobna palmovemu drevesu in tvoje prsi grozdom grozdja.',
        8: 'Rekel sem: »Šel bom gor k palmovemu drevesu, zgrabil bom njegove veje. Sedaj bodo tudi tvoje prsi kakor grozdi vinske trte in vonj tvojega nosu podoben jabolkom',
        9: '§ in nebo tvojih ust podobno najboljšemu vinu za mojega ljubljenega, ki gre medéno dol, povzročujoč ustnicam tistih, ki spijo, da spregovorijo.«',
        10: 'Jaz sem svojega ljubljenega in njegovo hrepenenje je po meni.',
        11: 'Pridi, moj ljubljeni, pojdiva na polje, prenočujva v vaseh.',
        12: 'Vstaniva zgodaj k vinogradom, poglejva, ali trta cveti, ali se pojavlja nežno grozdje in granatna jabolka brste. Tam ti bom dala svoje ljubezni.',
        13: 'Nadliščki dajejo vonj in pri naših velikih vratih so vse vrste prijetnih sadov, novi in stari, ki sem jih oskrbela zate, oh moj ljubljeni.',
    },
    8: {
        1: 'Oh, da bi bil kakor moj brat, ki je sesal prsi moje matere! Ko bi te našla zunaj, bi te poljubila, da, ne bi bila prezirana.',
        2: 'Vodila bi te in te privedla v hišo svoje matere, ki bi me poučila. Povzročila bi ti, da piješ dišeč vinski sok mojih granatnih jabolk.',
        3: 'Njegova leva roka bi bila pod mojo glavo in njegova desnica bi me objela.',
        4: 'Naročam vam, oh hčere jeruzalemske, da ne razvnamete niti ne zbudite moje ljubezni, dokler njemu ugaja.',
        5: 'Kdo je ta, ki prihaja iz divjine, naslonjena na svojega ljubljenega? Dvignil sem te pod jablano; tam te je rodila tvoja mati, tam te je rodila, ki te je nosila.',
        6: '§ Postavi me kakor pečat na svoje srce, kakor pečat na svoj laket, kajti ljubezen je močna kakor smrt, ljubosumje je kruto kakor grob. Njegovi ogorki so ognjeno oglje, ki ima najbolj silovit plamen.',
        7: 'Mnogo vodá ne more pogasiti ljubezni niti je poplave ne morejo potopiti. Če bi človek vse imetje svoje hiše dal za ljubezen, bi bil popolnoma zaničevan.',
        8: 'Imamo majhno sestro in ona nima prsi. Kaj bomo storili za svojo sestro na dan, ko jo bodo snubili?',
        9: 'Če bo zid, bomo na njej zgradili srebrno palačo in če bo vrata, jo bomo obdali s cedrovimi deskami.',
        10: 'Jaz sem zid in moje prsi kakor stolpa. Potem sem bila v njegovih očeh kakor nekdo, ki je našel naklonjenost.',
        11: 'Salomon je imel vinograd v Báal Hamónu; vinograd je dal v najem čuvajem. Vsak naj bi za njegov sad prinesel tisoč koščkov srebra.',
        12: 'Moj vinograd, ki je moj, je pred menoj. Ti, oh Salomon, moraš imeti tisoč, tisti, ki varujejo sad od njega, pa dvesto.',
        13: 'Ti, ki prebivaš v vrtovih, družabniki prisluhnejo tvojemu glasu; pripravi me, da ga slišim.',
        14: 'Podvizaj se, moj ljubljeni in bodi podoben srni ali mlademu jelenu na gorah dišav.',
    },
}
